{
  "candidates": [
    {
      "claimType": "preference",
      "statement": "个体近期社交偏好显著降低，更倾向于居家独处（阅读/游戏）作为主要休闲方式。",
      "supportingRefs": [
        "o1",
        "o2",
        "o3"
      ],
      "alternativeExplanations": [
        "客观限制：因工作忙碌、身体疲劳或外部约束导致无法参与社交，而非主观不想去。",
        "情境因素：特定时间段内无合适的社交对象或活动，导致频率自然下降。"
      ],
      "verificationPlan": [
        {
          "op": "searchCounterEvidence",
          "question": "检查近3个月是否有被拒绝的社交邀请记录，以区分‘不想动’与‘没机会’。"
        },
        {
          "op": "alignEvents",
          "question": "对比社交频率下降的时间点与工作压力峰值或生活变动事件是否重合。"
        }
      ],
      "whatWouldChangeTheAnswer": "若发现大量被拒记录或高压工作期，则从‘主动偏好改变’转为‘被动适应’或‘压力反应’。",
      "evidenceGrade": "支持",
      "action": "adopt"
    },
    {
      "claimType": "recurringBehavior",
      "statement": "个体的周末休闲行为模式已稳定转向以室内静态活动（读书、游戏）为主。",
      "supportingRefs": [
        "o3",
        "o4"
      ],
      "alternativeExplanations": [
        "短期尝试：这可能只是针对近期压力的临时放松策略，尚未形成稳定的长期习惯。",
        "任务驱动：这些完成记录可能源于特定的短期目标（如备考、通关），而非日常偏好。"
      ],
      "verificationPlan": [
        {
          "op": "comparePeriods",
          "question": "拉长观察窗口至6-12个月，确认该行为模式是近期突变还是长期趋势的延续。"
        },
        {
          "op": "checkCoverage",
          "question": "检查非周末时段的活动记录，确认居家活动是否仅局限于周末，还是渗透到了工作日。"
        }
      ],
      "whatWouldChangeTheAnswer": "若拉长周期后发现波动大或仅集中在特定任务期，则从‘稳定行为模式’降级为‘阶段性状态’。",
      "evidenceGrade": "线索",
      "action": "observe"
    }
  ]
}
